code.Java:
import java.util.concurrent.Executors;

public class Main {
    static String fetch(String name) throws InterruptedException {
        Thread.sleep(1000); // stands in for a network call
        return name + " done";
    }

    public static void main(String[] args) throws Exception {
        try (var pool = Executors.newVirtualThreadPerTaskExecutor()) {
            var users = pool.submit(() -> fetch("users"));
            var orders = pool.submit(() -> fetch("orders"));
            System.out.println(users.get() + ", " + orders.get()); // ~1 s total
        }
    }
}

