code.Go:
package main

import (
	"fmt"
	"sync"
	"time"
)

func fetch(name string) string {
	time.Sleep(time.Second) // stands in for a network call
	return name + " done"
}

func main() {
	names := []string{"users", "orders"}
	results := make([]string, len(names))
	var wg sync.WaitGroup
	for i, name := range names {
		wg.Add(1)
		go func() {
			defer wg.Done()
			results[i] = fetch(name)
		}()
	}
	wg.Wait()
	fmt.Println(results) // ~1 s total
}

code.Rust:
use std::thread;
use std::time::Duration;

fn fetch(name: &str) -> String {
    thread::sleep(Duration::from_secs(1)); // stands in for a network call
    format!("{name} done")
}

fn main() {
    let (users, orders) = thread::scope(|s| {
        let a = s.spawn(|| fetch("users"));
        let b = s.spawn(|| fetch("orders"));
        (a.join().unwrap(), b.join().unwrap())
    });
    println!("{users}, {orders}"); // ~1 s total
}
